-- Workspaces, their members and invitations.
--
-- Generated by Prisma, then edited by hand in two places, both marked below.

-- CreateEnum
CREATE TYPE "WorkspaceBusinessType" AS ENUM ('INDIVIDUAL_AGENT', 'BROKERAGE', 'CHANNEL_PARTNER', 'DEVELOPER', 'OTHER');

-- Hand-written, replacing Prisma's AlterEnum steps.
--
-- Both types were reserved by the init migration and never used by a column,
-- so they are recreated rather than altered. Prisma's generated steps failed
-- on both: its InvitationStatus rebuild altered workspace_invitations before
-- the table exists, and a value added with ADD VALUE cannot be used in the
-- transaction that adds it — the workspaces default below uses it. ADD VALUE
-- would also have appended PENDING_APPROVAL rather than placed it first.
DROP TYPE "WorkspaceStatus";
CREATE TYPE "WorkspaceStatus" AS ENUM ('PENDING_APPROVAL', 'ACTIVE', 'SUSPENDED', 'ARCHIVED', 'REJECTED');

DROP TYPE "InvitationStatus";
CREATE TYPE "InvitationStatus" AS ENUM ('PENDING', 'ACCEPTED', 'DECLINED', 'REVOKED', 'EXPIRED');

-- DropEnum
DROP TYPE "RoleSource";

