-- Hand-written: not expressible in schema.prisma (see the model comments).

-- One workspace awaiting review per owner: a signup cannot queue a hundred.
CREATE UNIQUE INDEX "workspaces_one_pending_per_owner_key"
    ON "workspaces" ("owner_user_id")
    WHERE "status" = 'PENDING_APPROVAL';

-- One pending invitation per address per workspace; a resolved one does not
-- block a new invitation.
CREATE UNIQUE INDEX "workspace_invitations_pending_key"
    ON "workspace_invitations" ("workspace_id", "email")
    WHERE "status" = 'PENDING';

-- The expiry sweep reads pending rows only.
CREATE INDEX "workspace_invitations_expiry_idx"
    ON "workspace_invitations" ("expires_at")
    WHERE "status" = 'PENDING';

-- Each status timestamp exists exactly while its status holds. Review is
-- one-sided: a workspace that never needed review is ACTIVE with none.
ALTER TABLE "workspaces"
    ADD CONSTRAINT "chk_workspaces_suspended"
        CHECK (("status" = 'SUSPENDED') = ("suspended_at" IS NOT NULL)),
    ADD CONSTRAINT "chk_workspaces_archived"
        CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL)),
    ADD CONSTRAINT "chk_workspaces_reviewed"
        CHECK (("status" <> 'PENDING_APPROVAL' OR "reviewed_at" IS NULL)
           AND ("status" <> 'REJECTED' OR "reviewed_at" IS NOT NULL));

-- Only a member active since creation has no status change recorded.
ALTER TABLE "workspace_members"
    ADD CONSTRAINT "chk_workspace_members_status_changed"
        CHECK ("status" = 'ACTIVE' OR "status_changed_at" IS NOT NULL);

-- An invitation is resolved exactly when it has left PENDING.
ALTER TABLE "workspace_invitations"
    ADD CONSTRAINT "chk_workspace_invitations_resolved"
        CHECK (("status" = 'PENDING') = ("resolved_at" IS NULL));
